=<!DOCTYPE html>
<html lang="pt-br">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta http-equiv="X-UA-Compatible" content="ie=edge">
<title>Alerta: Chat Aguardando Atendimento</title>
<style>
    body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
    table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
    img { -ms-interpolation-mode: bicubic; border: 0; height: auto; line-height: 100%; outline: none; text-decoration: none; }
    table { border-collapse: collapse !important; }
    body { height: 100% !important; margin: 0 !important; padding: 0 !important; width: 100% !important; background-color: #f0f2f5; }

    .email-container {
        max-width: 600px;
        margin: 0 auto;
        font-family: Arial, sans-serif;
        /* Sombra adicionada para dar profundidade */
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1 );
        border-radius: 8px; /* Bordas arredondadas para um visual mais moderno */
        overflow: hidden; /* Garante que a sombra não vaze para dentro */
    }
    .header {
        background-color: #696969; /* Cinza escurecido (DimGray), conforme solicitado */
        padding: 20px;
        text-align: center;
    }
    .main-content {
        background-color: #ffffff;
        padding: 40px 30px;
        text-align: center;
    }
    .main-content h1 {
        font-size: 24px;
        color: #333333; /* Cor do título ajustada para melhor contraste */
        margin-top: 0;
    }
    .main-content p {
        font-size: 16px;
        line-height: 1.6;
        color: #555555;
    }
    .info-box {
        text-align: left;
        border: 1px solid #eeeeee;
        background-color: #f9f9f9;
        padding: 20px;
        margin: 30px auto;
        max-width: 90%;
        border-radius: 5px;
    }
    .info-box p {
        margin: 8px 0;
        font-size: 15px;
    }
    .button {
        background-color: #696969; /* Cor do botão igual ao cabeçalho */
        color: #ffffff;
        padding: 15px 30px;
        text-decoration: none;
        border-radius: 5px;
        display: inline-block;
        font-weight: bold;
        margin-top: 20px;
    }
    .footer {
        background-color: #f7f7f7;
        color: #888888;
        padding: 20px;
        text-align: center;
        font-size: 12px;
    }
</style>
</head>
<body style="margin: 0 !important; padding: 0 !important; background-color: #f0f2f5;">
    <table border="0" cellpadding="0" cellspacing="0" width="100%">
        <tr>
            <td align="center" style="padding: 20px;">
                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="email-container">
                    <!-- CABEÇALHO -->
                    <tr>
                        <td class="header">
                            <img src="https://itease-my.sharepoint.com/personal/thais_goncalves_itease_com_br/_layouts/15/download.aspx?share=EVYX0OKxmmBFpzy-60P7No4BO-ihG50iFeuOl37PMMthxw" width="180" alt="Logo ITEASE" style="display: block; border: 0; font-family: Arial, sans-serif; font-size: 16px; color: #ffffff; font-weight: bold;">
                        </td>
                    </tr>

                    <!-- CONTEÚDO PRINCIPAL -->
                    <tr>
                        <td class="main-content">
                            <h1>Alerta: Chat Aguardando Atendimento</h1>
                            <p>
                                Um novo cliente iniciou um chat e aguarda o primeiro atendimento há <strong>{{ Math.round(DateTime.now(   ).diff(DateTime.fromISO($('Loop Over Items2').item.json.last_client_message), 'minutes').toObject().minutes) }}</strong> minutos.
                            </p>

                            <div class="info-box">
                                <p><strong>Cliente:</strong> {{ $json.requestor_name || 'Não identificado' }}</p>
                                <p><strong>Empresa:</strong> {{ $json.company_name || 'Não identificada' }}</p>
                                <p><strong>Ticket:</strong> </p>
                            </div>

                            <!-- BOTÃO DE AÇÃO -->
                            <a href="https://app.tiflux.com/v/chats" class="button" target="_blank">Atender Cliente</a>
                        </td>
                    </tr>

                    <!-- RODAPÉ -->
                    <tr>
                        <td class="footer">
                            <p>Este é um e-mail automático. Por favor, não responda.</p>
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>
</body>
</html>
